<script setup lang="ts">
import { ref } from 'vue';import { useRoute } from 'vue-router';import { api,auth,json } from '../api';
const route=useRoute(),mode=ref('login'),username=ref(''),password=ref(''),repeat=ref(''),invite=ref(''),show=ref(false),busy=ref(false),status=ref('');
async function submit(){if(busy.value)return;if(mode.value==='register'&&password.value!==repeat.value){status.value='两次密码不一致';return;}busy.value=true;status.value='正在处理…';try{let endpoint='';if(mode.value==='login'&&'serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration('/');const sub=await reg?.pushManager?.getSubscription();endpoint=sub?.endpoint||'';if(sub&&!await sub.unsubscribe())throw Error('旧通知未能关闭，请重试');}
 await api('/api/auth/'+mode.value,{method:'POST',body:json({username:username.value,password:password.value,invite_code:invite.value,endpoint})});
 if(mode.value==='register'){mode.value='login';password.value=repeat.value=invite.value='';status.value='注册成功，请登录。';}
 else{localStorage.setItem('companion-notifications-disabled','true');localStorage.removeItem('companion-web-push');localStorage.setItem('chat-account-changed',String(Date.now()));const url=new URL(String(route.query.next||'/'),location.origin);location.assign(url.origin===location.origin&&['/','/chat'].includes(url.pathname)?url.pathname+url.search:'/');}
 }catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><main class="login"><form class="login-card" @submit.prevent="submit"><h1>会话</h1><p class="muted">登录后，继续你的故事。</p><nav class="tabs"><button type="button" :class="{active:mode==='login'}" @click="mode='login'" :disabled="busy">登录</button><button v-if="auth.registration_mode!=='closed'" type="button" :class="{active:mode==='register'}" @click="mode='register'" :disabled="busy">注册</button></nav><label>用户名<input v-model.trim="username" autocomplete="username" required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_\-]+"></label><label for="loginPassword">密码</label><div class="password"><input id="loginPassword" v-model="password" :type="show?'text':'password'" :autocomplete="mode==='login'?'current-password':'new-password'" :minlength="mode==='register'?10:1" maxlength="128" required><button type="button" @click="show=!show">{{show?'隐藏':'显示'}}</button></div><template v-if="mode==='register'"><label>确认密码<input v-model="repeat" type="password" autocomplete="new-password" required></label><label v-if="auth.registration_mode==='invite'">邀请码<input v-model.trim="invite" required autocomplete="off"></label></template><p role="status" class="feedback">{{status}}</p><button class="primary wide" :disabled="busy">{{mode==='login'?'登录':'创建账号'}}</button><p class="muted">忘记密码？请联系管理员重置。</p></form></main></template>
